-- Table: test_results_all
DROP TABLE IF EXISTS "test_results_all" CASCADE;
CREATE TABLE IF NOT EXISTS "test_results_all" (
    "category" TEXT,
    "created_at" TIMESTAMPTZ,
    "delete_status" INTEGER,
    "id" INTEGER,
    "mr_no" INTEGER,
    "patient_name" TEXT,
    "person_deleting" TEXT,
    "remarks" TEXT,
    "status" BOOLEAN,
    "test_name" TEXT,
    "test_values" JSONB,
    PRIMARY KEY ("id")
);

ON CONFLICT DO NOTHING;
